/**
 * More families whose dedicated servers register on the Steam master list. These app ids are from Valve's public
 * store and are NOT in the sweep until an admin lists the family in Setting `directory_steam_extra_games`
 * (comma separated), because each one needs an owner-approved one-off sample call first: if the list answers
 * with no rows (or only another game), the family belongs in the "no public source" bucket and stays off.
 * UNVERIFIED against the live API in this branch (no key available to the build agent): see docs/DIRECTORY-SOURCES.md.
 */
export const STEAM_EXTRA_APPIDS: Record<string, number> = {
  cs16: 10, dayz: 221100, arma3: 107410, squad: 393380, mordhau: 629760, kf2: 232090, sandstorm: 581320,
  barotrauma: 602960, spaceengineers: 244850, empyrion: 383120, stationeers: 544550, theforest: 242760,
  sonsoftheforest: 1326470, vrising: 1604030, abioticfactor: 427410, soulmask: 2646460, theisle: 376210,
  enshrouded: 1203620, icarus: 1149460,
};
export const ALL_STEAM_APPIDS: Record<string, number> = { ...STEAM_EXTRA_APPIDS, ...VALVE_APPIDS };

/** Families the sweep refreshes: the proven base set plus the extras an admin enabled (unknown names are ignored). */
export function sweepGames(extraCsv: string): string[] {
  const extra = extraCsv.split(",").map((g) => g.trim().toLowerCase()).filter((g) => STEAM_EXTRA_APPIDS[g] && !VALVE_APPIDS[g]);
  return [...Object.keys(VALVE_APPIDS), ...new Set(extra)];
}

export type ValveRaw = {
  addr?: string; gameport?: number; name?: string; appid?: number; version?: string;
  players?: number; max_players?: number; bots?: number; map?: string; dedicated?: boolean; gametype?: string;
};

export type ExternalCandidate = {
  source: "valve";
  sourceKey: string;
  game: string;
  name: string;
  host: string;
  ip: string;
  port: number;
  queryPort: number | null;
  map: string | null;
  players: number | null;
  maxPlayers: number | null;
  version: string | null;
  tags: string[];
  connKey: string;
  ipKey: string;
};

const num = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) && v >= 0 ? Math.floor(v) : null);

/** Server names come from strangers: strip controls, collapse space, bound length, drop empties/links-only. */
export function cleanServerName(raw: unknown): string | null {
  const t = cleanText(raw, 80);
  if (!t || t.length < 3) return null;
  if (!/[\p{L}\p{N}]/u.test(t)) return null;
  return t;
}

export function parseValveRow(game: string, r: ValveRaw): ExternalCandidate | null {
  const m = /^(\d{1,3}(?:\.\d{1,3}){3}):(\d{1,5})$/.exec(String(r.addr ?? ""));
  if (!m) return null;
  const ip = normalizeHost(m[1]);
  if (!isIpv4(ip) || /^(0\.|10\.|127\.|169\.254\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(ip)) return null;
  const queryPort = Number(m[2]);
  // The join port is `gameport` when the row reports one; otherwise the address port.
  const port = num(r.gameport) && num(r.gameport)! > 0 && num(r.gameport)! < 65536 ? num(r.gameport)! : queryPort;
  if (!(port >= 1 && port <= 65535)) return null;
  const name = cleanServerName(r.name);
  if (!name) return null;
  if (r.dedicated === false) return null;
  const tags = String(r.gametype ?? "").split(",").map((t) => cleanText(t, 24)).filter((t): t is string => !!t).slice(0, 8);
  const key = connKey(game, ip, port);
  return {
    source: "valve", sourceKey: `${ip}:${port}`, game, name, host: ip, ip, port,
    queryPort: queryPort !== port ? queryPort : null,
    map: cleanText(r.map, 40), players: num(r.players), maxPlayers: num(r.max_players),
    version: cleanText(r.version, 24), tags, connKey: key, ipKey: key,
  };
}

export function parseValveResponse(game: string, json: unknown): ExternalCandidate[] {
  const rows = (json as { response?: { servers?: ValveRaw[] } } | null)?.response?.servers;
  if (!Array.isArray(rows)) return [];
  const seen = new Set<string>();
  const out: ExternalCandidate[] = [];
  for (const r of rows) {
    const c = parseValveRow(game, r);
    if (!c || seen.has(c.sourceKey)) continue;
    seen.add(c.sourceKey);
    out.push(c);
  }
  return out;
}

/** `status` = the HTTP status when Steam answered one; `retryAfterSec` = its Retry-After header when sent. */
export class ValveFetchError extends Error {
  constructor(message: string, readonly status?: number, readonly retryAfterSec?: number) { super(message); }
}

/** One bounded request. Throws ValveFetchError on anything but a clean 200 JSON body. */
export async function fetchValveList(game: string, opts: { key: string; limit?: number; timeoutMs?: number; fetchImpl?: typeof fetch }): Promise<ExternalCandidate[]> {
  const appid = ALL_STEAM_APPIDS[game];
  if (!appid) throw new ValveFetchError(`No Steam app id known for ${game}`);
  const limit = Math.min(Math.max(opts.limit ?? 1000, 1), 5000);
  // dedicated + at least one open slot is not required; empty servers are useful listings too.
  const filter = `\\appid\\${appid}\\dedicated\\1`;
  const url = `https://api.steampowered.com/IGameServersService/GetServerList/v1/?key=${encodeURIComponent(opts.key)}&limit=${limit}&filter=${encodeURIComponent(filter)}`;
  const ctl = new AbortController();
  const t = setTimeout(() => ctl.abort(), opts.timeoutMs ?? 25_000);
  try {
    const res = await (opts.fetchImpl ?? fetch)(url, { signal: ctl.signal, headers: { accept: "application/json" } });
    if (!res.ok) {
      const ra = Number(res.headers?.get?.("retry-after"));
      throw new ValveFetchError(`Steam list answered HTTP ${res.status}`, res.status, Number.isFinite(ra) && ra > 0 ? ra : undefined);
    }
    return parseValveResponse(game, await res.json());
  } catch (e) {
    if (e instanceof ValveFetchError) throw e;
    // never echo the URL (it carries the API key)
    throw new ValveFetchError(e instanceof Error && e.name === "AbortError" ? "Steam list timed out" : "Steam list request failed");
  } finally {
    clearTimeout(t);
  }
}
import { db } from "@/lib/db";
import { getSetting, setSetting } from "@/lib/settings";
import { ingestValveGame, type IngestResult } from "./run";
import type { ReverseFn } from "./ptr";
import { sweepGames, ValveFetchError } from "./valve";
import { loadSteamConfig } from "./gates";
import {
  backoffMs, breakerDecision, callsRemaining, dayKey, dueGames, sweepGate, type SweepSkip,
} from "./schedule";

/**
 * The Steam list sweep: what the worker runs every few minutes (worker/directory.ts). Each tick decides,
 * in a pinned order (schedule.ts sweepGate), whether it may run at all; then refreshes at most
 * MAX_GAMES_PER_TICK games that are due, ONE Steam request each, counting every request against the daily cap.
 * A failure backs off exponentially and stops the tick; repeated failures open the breaker; a 401/403
 * opens it AND switches the sweep off. All state is in DirectorySource("steam"), so restarts resume.
 */
export const STEAM_SOURCE = "steam";
const CLAIM_MS = 10 * 60_000;
export const SWEEP_LIMIT = 1000;

export type SweepGameResult = { game: string; ok: boolean; error?: string; result?: IngestResult };
export type SweepReport = { skipped?: SweepSkip; games: SweepGameResult[]; disabled?: boolean };

export async function ensureSource(key: string) {
  return db.directorySource.upsert({ where: { key }, create: { key }, update: {} });
}

/** Strip anything that could be the API key from a message headed for the database. */
export function redactKey(msg: string, key: string | undefined): string {
  let m = msg;
  if (key) m = m.split(key).join("[key]");
  return m.replace(/key=[A-Za-z0-9]+/g, "key=[key]").slice(0, 300);
}

export async function directorySweepTick(opts: {
  now?: number; key?: string; fetchImpl?: typeof fetch; ingest?: typeof ingestValveGame; envKill?: boolean; reverse?: ReverseFn;
} = {}): Promise<SweepReport> {
  const now = opts.now ?? Date.now();
  const key = opts.key ?? process.env.STEAM_WEB_API_KEY;
  const ingest = opts.ingest ?? ingestValveGame;
  const cfg = await loadSteamConfig();
  const src = await ensureSource(STEAM_SOURCE);
  const skip = sweepGate({
    envKill: opts.envKill ?? process.env.DIRECTORY_SWEEP_DISABLED === "1",
    ingestOn: cfg.ingestOn, sweepOn: cfg.sweepOn, legalProblems: cfg.legalProblems, hasKey: !!key,
    circuitOpenUntil: src.circuitOpenUntil, nextAttemptAt: src.nextAttemptAt, runningUntil: src.runningUntil,
    remainingCalls: callsRemaining(src, now), now,
  });
  if (skip) {
    if (skip === "no-key") {
      await db.directorySource.update({ where: { key: STEAM_SOURCE }, data: { lastError: "Needs STEAM_WEB_API_KEY in the worker's environment.", lastErrorAt: new Date(now), nextAttemptAt: new Date(now + 3600_000) } });
    }
    return { skipped: skip, games: [] };
  }
  // Claim: two worker processes must never sweep at once.
  const claimed = await db.directorySource.updateMany({
    where: { key: STEAM_SOURCE, OR: [{ runningUntil: null }, { runningUntil: { lt: new Date(now) } }] },
    data: { runningUntil: new Date(now + CLAIM_MS) },
  });
  if (!claimed.count) return { skipped: "running", games: [] };

  const force = src.runRequested;
  const report: SweepReport = { games: [] };
  let callsDay = src.callsDay, callsToday = src.callsDay === dayKey(now) ? src.callsToday : 0;
  let errors = src.consecutiveErrors, lastOkAt = src.lastOkAt, lastError = src.lastError, lastErrorAt = src.lastErrorAt;
  let circuit: Date | null = null, next: Date | null = null;
  try {
    const rows = await db.directoryIngestRun.groupBy({
      by: ["game"], where: { source: "valve", status: { in: ["ok", "suspicious"] }, finishedAt: { not: null } }, _max: { finishedAt: true },
    });
    const last = new Map(rows.map((r) => [r.game, r._max.finishedAt]));
    const due = dueGames(sweepGames(await getSetting("directory_steam_extra_games", "")), last, now, { baseMin: cfg.intervalMin, force });
    if (!due.length) report.skipped = "nothing-due";
    for (const game of due) {
      if (callsRemaining({ callsDay, callsToday }, now) <= 0) { report.skipped = "budget"; break; }
      callsDay = dayKey(now); callsToday += 1; // counted BEFORE the call: a failed request still spent budget
      try {
        const result = await ingest(game, { apply: true, key: key!, limit: SWEEP_LIMIT, fetchImpl: opts.fetchImpl, reverse: opts.reverse, trigger: force ? "admin" : "worker" });
        report.games.push({ game, ok: true, result });
        errors = 0; lastOkAt = new Date(now); lastError = null; lastErrorAt = null; circuit = null; next = null;
      } catch (e) {
        const status = e instanceof ValveFetchError ? e.status : undefined;
        const msg = redactKey(e instanceof Error ? e.message : "sweep failed", key);
        errors += 1; lastError = `${game}: ${msg}`; lastErrorAt = new Date(now);
        const b = breakerDecision(errors, status);
        next = new Date(now + backoffMs(errors, e instanceof ValveFetchError ? e.retryAfterSec : undefined));
        if (b.open) circuit = new Date(now + b.openMs);
        if (b.disable) {
          await setSetting("directory_sweep_enabled", "false");
          report.disabled = true;
          console.error(`[directory] Steam answered HTTP ${status}: sweep switched OFF. Check the key and Valve's terms before turning it back on.`);
        }
        report.games.push({ game, ok: false, error: msg });
        break; // never hammer the next game after a failure
      }
    }
  } finally {
    await db.directorySource.update({
      where: { key: STEAM_SOURCE },
      data: {
        runningUntil: null, runRequested: false, lastRunAt: new Date(now), lastOkAt, lastError, lastErrorAt,
        consecutiveErrors: errors, circuitOpenUntil: circuit ?? (errors === 0 ? null : src.circuitOpenUntil),
        nextAttemptAt: next, callsDay, callsToday,
        stats: { games: report.games.map((g) => ({ game: g.game, ok: g.ok, fetched: g.result?.fetched ?? null })), skipped: report.skipped ?? null },
      },
    });
  }
  return report;
}
import { db } from "@/lib/db";
import { getSettingBool } from "@/lib/settings";
import { nxeonConnectionKeys } from "@/lib/server-directory-data";
import { loadRuleSet } from "@/lib/directory-blocklist-db";
import { evaluateHost, describeVerdict, type RuleSet } from "@/lib/directory-blocklist";
import { resolvePtrs, PTR_TTL_MS, type ReverseFn } from "./ptr";
import { isIpv4 } from "@/lib/server-directory";
import { fetchValveList, ALL_STEAM_APPIDS, ValveFetchError, type ExternalCandidate } from "./valve";
import { assertSteamLegalGate } from "./gates";
import { isSuspiciousShrink } from "./schedule";

/**
 * Ingest one game from the Steam master list into ExternalServer. Gated:
 * `apply` writes only when Setting directory_ingest_enabled is true. Dry run
 * (default) fetches + counts and writes nothing.
 *
 * Dedupe at the door: a candidate whose connection (host:port or ip:port)
 * equals something Nxeon hosts is dropped — the directory shows OUR entry
 * (with the Nxeon badge), not a duplicate. Candidates already stored under the
 * same connKey from another source row are skipped too. Rows not seen for
 * PRUNE_AFTER_DAYS are deleted so a dead server does not linger.
 */
export const PRUNE_AFTER_DAYS = 3;

export type IngestResult = { game: string; fetched: number; inserted: number; updated: number; duplicates: number; pruned: number; blocked: number; dryRun: boolean; suspicious: boolean };

export type PtrCache = Map<string, { ptrName: string | null; checkedAt: Date | null }>;
/** A found name is trusted 30 days; "no answer" only 1 day (a timeout must not stick). */
export function ptrFresh(c: { ptrName: string | null; checkedAt: Date | null } | undefined, now = Date.now()): boolean {
  if (!c?.checkedAt) return false;
  return now - c.checkedAt.getTime() < (c.ptrName ? PTR_TTL_MS : 86_400_000);
}

export type BlockVerdictRow<T> = { cand: T; ptrName: string | null; ptrCheckedAt: Date | null; blockedReason: string | null; blockedRule: string | null };

/**
 * Judge each candidate against the blocklist. Hostnames are judged directly;
 * IP-only candidates by their reverse-DNS name, taken from `cache` while fresh
 * and otherwise looked up here (bounded, see ptr.ts). Pure apart from `reverse`.
 */
export async function judgeCandidates<T extends { host: string; port: number }>(
  cands: T[], set: RuleSet, cache: PtrCache, opts: { reverse?: ReverseFn; now?: Date } = {},
): Promise<BlockVerdictRow<T>[]> {
  const now = opts.now ?? new Date();
  const isIp = (h: string) => isIpv4(h) || h.includes(":");
  const need = cands.filter((c) => isIp(c.host) && !ptrFresh(cache.get(c.host), now.getTime())).map((c) => c.host);
  const looked = need.length ? await resolvePtrs(need, { reverse: opts.reverse }) : new Map<string, string | null>();
  return cands.map((cand) => {
    let ptrName: string | null = null, ptrCheckedAt: Date | null = null;
    if (isIp(cand.host)) {
      if (looked.has(cand.host)) { ptrName = looked.get(cand.host) ?? null; ptrCheckedAt = now; }
      else { const c = cache.get(cand.host); ptrName = c?.ptrName ?? null; ptrCheckedAt = c?.checkedAt ?? null; }
    }
    const v = evaluateHost(cand.host, cand.port, set, { ptr: ptrName });
    return { cand, ptrName, ptrCheckedAt, blockedReason: describeVerdict(v), blockedRule: v.rule?.id ?? null };
  });
}

export function splitDuplicates<T extends { connKey: string; ipKey: string | null }>(cands: T[], nxeonKeys: Set<string>): { keep: T[]; dup: number } {
  const seen = new Set<string>();
  const keep: T[] = [];
  let dup = 0;
  for (const c of cands) {
    const keys = [c.connKey, ...(c.ipKey ? [c.ipKey] : [])];
    if (keys.some((k) => nxeonKeys.has(k) || seen.has(k))) { dup++; continue; }
    keys.forEach((k) => seen.add(k));
    keep.push(c);
  }
  return { keep, dup };
}

export type IngestTrigger = "worker" | "cli" | "admin";

/**
 * ONE Steam request for `game`, then parse -> dedupe -> blocklist -> upsert -> prune. `apply` writes only
 * when directory_ingest_enabled is on AND the legal checkpoints (storage country, terms reviewer) are
 * recorded. A list that shrank sharply against what we hold is "suspicious": rows are refreshed but NOTHING
 * is pruned, so one bad Steam answer cannot empty the directory.
 */
export async function ingestValveGame(game: string, opts: { apply: boolean; key: string; limit?: number; fetchImpl?: typeof fetch; reverse?: ReverseFn; trigger?: IngestTrigger }): Promise<IngestResult> {
  if (!ALL_STEAM_APPIDS[game]) throw new Error(`Unsupported game for the Steam list: ${game}`);
  if (opts.apply && !(await getSettingBool("directory_ingest_enabled", false))) {
    throw new Error("Ingestion is switched off (Setting directory_ingest_enabled). Turn it on in /admin/directory first.");
  }
  if (opts.apply) await assertSteamLegalGate();
  const run = opts.apply ? await db.directoryIngestRun.create({ data: { source: "valve", game, trigger: opts.trigger ?? "cli", status: "error" } }) : null;
  try {
    const fetched = await fetchValveList(game, { key: opts.key, limit: opts.limit, fetchImpl: opts.fetchImpl });
    const nxKeys = await nxeonConnectionKeys();
    const { keep, dup } = splitDuplicates<ExternalCandidate>(fetched, nxKeys);
    let inserted = 0, updated = 0, pruned = 0, blocked = 0, suspicious = false;
    // Competitor-host blocklist. Blocked rows are STORED with a verdict (so admins can see what
    // was dropped and why, and re-evaluate when rules change) and filtered out of every display query.
    const { set } = await loadRuleSet();
    const existingRows = await db.externalServer.findMany({ where: { source: "valve", game }, select: { id: true, sourceKey: true, host: true, ptrName: true, ptrCheckedAt: true, lastSeenAt: true } });
    const cache: PtrCache = new Map(existingRows.map((r) => [r.host, { ptrName: r.ptrName, checkedAt: r.ptrCheckedAt }]));
    const judged = await judgeCandidates(keep, set, cache, { reverse: opts.reverse });
    blocked = judged.filter((j) => j.blockedReason).length;
    if (opts.apply) {
      const existing = new Map(existingRows.map((r) => [r.sourceKey, r.id]));
      const now = new Date();
      for (let i = 0; i < judged.length; i += 100) {
        await db.$transaction(judged.slice(i, i + 100).map(({ cand: c, ptrName, ptrCheckedAt, blockedReason, blockedRule }) => {
          const data = {
            blockedReason, blockedRule, ptrName, ptrCheckedAt,
            game: c.game, name: c.name, host: c.host, ip: c.ip, port: c.port, queryPort: c.queryPort, map: c.map,
            players: c.players, maxPlayers: c.maxPlayers, version: c.version, tags: c.tags,
            connKey: c.connKey, ipKey: c.ipKey, lastSeenAt: now,
          };
          if (existing.has(c.sourceKey)) updated++; else inserted++;
          return db.externalServer.upsert({
            where: { source_sourceKey: { source: "valve", sourceKey: c.sourceKey } },
            create: { source: "valve", sourceKey: c.sourceKey, ...data }, update: data,
          });
        }));
      }
      // Rows that now collide with something Nxeon hosts are removed (they were listed before we hosted them).
      // "previous" = rows the list still showed a day ago (not stale leftovers), compared with what this answer holds.
      const previous = existingRows.filter((r) => Date.now() - r.lastSeenAt.getTime() < 86_400_000).length;
      suspicious = isSuspiciousShrink(previous, keep.length);
      const gone = await db.externalServer.deleteMany({
        where: {
          source: "valve", game,
          OR: [...(suspicious ? [] : [{ lastSeenAt: { lt: new Date(Date.now() - PRUNE_AFTER_DAYS * 86_400_000) } }]), { connKey: { in: [...nxKeys] } }],
        },
      });
      pruned = gone.count;
      await db.directoryIngestRun.update({
        where: { id: run!.id },
        data: {
          finishedAt: new Date(), fetched: fetched.length, inserted, updated, duplicates: dup, pruned, blocked,
          status: suspicious ? "suspicious" : "ok",
          note: suspicious ? `List shrank from ${previous} to ${keep.length} rows: kept old rows, pruned nothing.` : null,
          error: null,
        },
      });
    }
    return { game, fetched: fetched.length, inserted, updated, duplicates: dup, pruned, blocked, dryRun: !opts.apply, suspicious };
  } catch (e) {
    const msg = e instanceof ValveFetchError ? e.message : e instanceof Error ? e.message : "ingest failed";
    if (run) await db.directoryIngestRun.update({ where: { id: run.id }, data: { finishedAt: new Date(), status: "error", error: msg.slice(0, 300) } }).catch(() => {});
    throw e;
  }
}

/**
 * Steam sweep scheduling, backoff, circuit breaker and call budget. PURE (clock passed in) and
 * unit-tested (test/directory-sweep.test.ts). The database half is lib/directory-ingest/sweep.ts.
 *
 * Design numbers (the plan, section 4.2): one Steam request per game per run, each game refreshed about
 * hourly (the big, low-value lists every three hours), at most MAX_GAMES_PER_TICK games per 5 minute tick,
 * a hard daily cap far under Valve's 100,000, exponential backoff on failure, and a breaker that opens for
 * six hours after repeated failures or on a 401/403 (key revoked/forbidden), which also switches the sweep off.
 */
import { STEAM_DAILY_CALL_CAP } from "@/lib/directory-steam";

export const MAX_GAMES_PER_TICK = 2;
export const MIN_INTERVAL_MIN = 30;
export const MAX_INTERVAL_MIN = 1440;
export const DEFAULT_INTERVAL_MIN = 60;
/** Lists that are huge and change little in value per refresh run less often. */
export const SLOW_GAMES: ReadonlySet<string> = new Set(["rust", "cs2", "gmod"]);
export const SLOW_FACTOR = 3;

export const BACKOFF_BASE_MS = 5 * 60_000;
export const BACKOFF_MAX_MS = 6 * 3600_000;
export const BREAKER_AFTER_ERRORS = 5;
export const BREAKER_OPEN_MS = 6 * 3600_000;

/** A sweep that fetches under this share of what the game had last time is not trusted (outage / partial answer). */
export const SHRINK_KEEP_RATIO = 0.4;
export const SHRINK_MIN_PREVIOUS = 50;

export function clampIntervalMin(v: number): number {
  if (!Number.isFinite(v)) return DEFAULT_INTERVAL_MIN;
  return Math.min(MAX_INTERVAL_MIN, Math.max(MIN_INTERVAL_MIN, Math.round(v)));
}

export const gameIntervalMs = (game: string, baseMin: number): number =>
  clampIntervalMin(baseMin) * 60_000 * (SLOW_GAMES.has(game) ? SLOW_FACTOR : 1);

/** Games due now, longest-waiting first (never-run first), bounded per tick. `force` ignores the per-game schedule once. */
export function dueGames(
  games: string[], lastOkAt: Map<string, Date | null | undefined>, now: number,
  opts: { baseMin: number; force?: boolean; max?: number },
): string[] {
  const due = games
    .filter((g) => opts.force || !lastOkAt.get(g) || now - lastOkAt.get(g)!.getTime() >= gameIntervalMs(g, opts.baseMin))
    .sort((a, b) => (lastOkAt.get(a)?.getTime() ?? 0) - (lastOkAt.get(b)?.getTime() ?? 0));
  return due.slice(0, opts.max ?? MAX_GAMES_PER_TICK);
}

/** Exponential backoff after the n-th consecutive failure (n >= 1): 5, 10, 20 ... capped at 6 h; honours Retry-After. */
export function backoffMs(consecutiveErrors: number, retryAfterSec?: number): number {
  const n = Math.max(1, consecutiveErrors);
  const exp = Math.min(BACKOFF_MAX_MS, BACKOFF_BASE_MS * 2 ** Math.min(n - 1, 12));
  const ra = retryAfterSec && retryAfterSec > 0 ? Math.min(retryAfterSec * 1000, BACKOFF_MAX_MS) : 0;
  return Math.max(exp, ra);
}

export type BreakerDecision = { open: boolean; disable: boolean; openMs: number };

/**
 * After a failure: `consecutiveErrors` already includes it. 401/403 means the key was revoked or the use
 * was refused: open the breaker AND disable the sweep (a human must look). Otherwise open after N in a row.
 */
export function breakerDecision(consecutiveErrors: number, httpStatus?: number): BreakerDecision {
  if (httpStatus === 401 || httpStatus === 403) return { open: true, disable: true, openMs: BREAKER_OPEN_MS };
  if (consecutiveErrors >= BREAKER_AFTER_ERRORS) return { open: true, disable: false, openMs: BREAKER_OPEN_MS };
  return { open: false, disable: false, openMs: 0 };
}

export const dayKey = (now: number): string => new Date(now).toISOString().slice(0, 10);

/** Calls still allowed today under OUR cap (resets at 00:00 UTC). */
export function callsRemaining(state: { callsDay: string | null; callsToday: number }, now: number, cap = STEAM_DAILY_CALL_CAP): number {
  const used = state.callsDay === dayKey(now) ? state.callsToday : 0;
  return Math.max(0, cap - used);
}

/** True when the list shrank so sharply that old rows must be kept and nothing pruned this run. */
export function isSuspiciousShrink(previous: number, fetched: number): boolean {
  return previous >= SHRINK_MIN_PREVIOUS && fetched < previous * SHRINK_KEEP_RATIO;
}

export type SweepSkip = "kill-switch" | "disabled" | "legal-gate" | "no-key" | "circuit-open" | "backoff" | "budget" | "running" | "nothing-due";

/** The order in which the worker decides not to run, as pure logic so the order is pinned by tests. */
export function sweepGate(i: {
  envKill: boolean; ingestOn: boolean; sweepOn: boolean; legalProblems: string[]; hasKey: boolean;
  circuitOpenUntil: Date | null; nextAttemptAt: Date | null; runningUntil: Date | null; remainingCalls: number; now: number;
}): SweepSkip | null {
  if (i.envKill) return "kill-switch";
  if (!i.ingestOn || !i.sweepOn) return "disabled";
  if (i.legalProblems.length) return "legal-gate";
  if (!i.hasKey) return "no-key";
  if (i.runningUntil && i.runningUntil.getTime() > i.now) return "running";
  if (i.circuitOpenUntil && i.circuitOpenUntil.getTime() > i.now) return "circuit-open";
  if (i.nextAttemptAt && i.nextAttemptAt.getTime() > i.now) return "backoff";
  if (i.remainingCalls <= 0) return "budget";
  return null;
}
import fs from "node:fs";
import path from "node:path";

/**
 * Everything the Valve/Steam terms make us do, in one place (docs/DOCUMENTATION.md "Steam ingest and
 * liveness"; the plan is /root/research/directory-v2-plan.md section 2.2 S1). The terms are at
 * https://steamcommunity.com/dev/apiterms. The clauses that shape the code:
 *  - attribute Valve (name, logo, a normal followed link) on every page that shows Steam data
 *  - never present the data so it appears Valve endorses us or the data is "available from a third party"
 *  - say in our privacy policy in which country the Steam data is stored
 *  - at most 100,000 Steam Web API calls per day (we spend a few hundred, hard-capped far below that)
 *  - Valve may revoke access at any time (a 401/403 trips the breaker and switches the sweep off)
 * Not legal advice: the owner reads the terms; the gates below only make sure the code cannot run
 * until the owner has said they did.
 */

/** Hard ceiling for OUR Steam list calls per UTC day. Valve's limit is 100,000 per key and the key is shared with the Workshop sync. */
export const STEAM_DAILY_CALL_CAP = 2000;
/** The limit in Valve's terms, shown on the admin page next to our usage. */
export const STEAM_TERMS_DAILY_LIMIT = 100_000;

// Attribution text lives in the client-safe lib/directory-attribution.ts (single source of truth).
import { STEAM_ATTRIBUTION_TEXT, STEAM_LINK } from "@/lib/directory-attribution";
export { STEAM_ATTRIBUTION_TEXT, STEAM_LINK };
export const VALVE_LINK = "https://www.valvesoftware.com/";
/** Drop the official Steam logo from Valve's brand assets here (the owner supplies it; we never draw our own). */
export const STEAM_LOGO_PUBLIC_PATH = "/brand/steam-logo.svg";

export type SteamGateInput = { storageCountry: string; termsReviewedBy: string; hasKey: boolean };

/** Reasons the Steam sweep/ingest must not run yet (empty = clear). The key is NOT part of the legal gate. */
export function steamLegalGate(i: Pick<SteamGateInput, "storageCountry" | "termsReviewedBy">): string[] {
  const out: string[] = [];
  if (!i.storageCountry.trim()) out.push("Set the country where the Steam data is stored (it must match the privacy policy).");
  if (!i.termsReviewedBy.trim()) out.push("Record who read the Steam Web API terms (https://steamcommunity.com/dev/apiterms).");
  return out;
}

/** True when the optional official logo file has been supplied. Server-side only. */
export function steamLogoPresent(root = process.cwd()): boolean {
  try { return fs.existsSync(path.join(root, "public", STEAM_LOGO_PUBLIC_PATH)); } catch { return false; }
}

const escHtml = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

/**
 * The attribution block rendered on every public page that lists Steam-found servers. Links are plain
 * (rel="noopener" only, NEVER nofollow: the terms forbid it). The wording says "found through" and that
 * Nxeon checks the servers itself; it never says Valve provides, hosts, endorses or powers this.
 */
export function steamAttributionHtml(opts: { logo: boolean }): string {
  const logo = opts.logo
    ? `<a class="dr-steam-logo" href="${STEAM_LINK}" rel="noopener"><img src="${STEAM_LOGO_PUBLIC_PATH}" alt="Steam" height="22" loading="lazy" decoding="async"></a>`
    : "";
  return `<aside class="dr-attrib" aria-label="Steam attribution" data-attrib="steam">${logo}<p>`
    + `Some of these servers were found through the <a href="${STEAM_LINK}" rel="noopener">Steam</a> server list. `
    + `Nxeon then checks each one directly, and the player counts shown come from the servers themselves. `
    + `Steam and the Steam logo are trademarks of <a href="${VALVE_LINK}" rel="noopener">Valve Corporation</a>. `
    + `Nxeon is not affiliated with, endorsed by or sponsored by Valve, and Valve does not host or provide this directory.`
    + `</p></aside>`;
}

/**
 * DRAFT privacy-policy paragraph for the owner (not published anywhere automatically).
 * `country` comes from Setting directory_storage_country so the policy and the config cannot drift apart.
 */
export function steamPrivacyDraft(opts: { country: string; contact: string }): string {
  const c = escHtml(opts.country.trim() || "[COUNTRY: set directory_storage_country]");
  return `Server directory. To build our public server directory we retrieve public game-server listings (a server's address, name, map, `
    + `player counts and version) from the Steam Web API operated by Valve Corporation, and we check those servers directly. `
    + `We store this data in ${c}. It describes game servers, not Steam users: we do not collect Steam user profiles, Steam IDs or `
    + `player names for the directory. Server addresses are shown publicly in the directory. If a server of yours is listed and you `
    + `would like it removed, contact ${escHtml(opts.contact)} and we will remove it.`;
}
