test("call budget: our cap is far below Valve's, resets each UTC day", () => {
  assert.ok(STEAM_DAILY_CALL_CAP <= STEAM_TERMS_DAILY_LIMIT / 10);
  const today = dayKey(NOW);
  assert.equal(callsRemaining({ callsDay: today, callsToday: 5 }, NOW), STEAM_DAILY_CALL_CAP - 5);
  assert.equal(callsRemaining({ callsDay: "2026-10-03", callsToday: STEAM_DAILY_CALL_CAP }, NOW), STEAM_DAILY_CALL_CAP, "yesterday's count does not carry over");
  assert.equal(callsRemaining({ callsDay: today, callsToday: STEAM_DAILY_CALL_CAP + 50 }, NOW), 0);
  // 11 games, each refreshed at least hourly (rust/cs2/gmod every 3 h): well under the cap even at the 30 minute floor.
  const perDay = Object.keys(VALVE_APPIDS).reduce((n, g) => n + (24 * 3600_000) / gameIntervalMs(g, 30), 0);
  assert.ok(perDay < STEAM_DAILY_CALL_CAP / 2, `${perDay} calls/day at the fastest schedule`);
});

