    url = os.environ.get("DATABASE_URL")
    if not url:
        sys.exit("DATABASE_URL not set (run: set -a; . /opt/nxeon/.env; set +a)")
    url = url.split("?")[0]  # drop prisma's ?schema=...
    r = subprocess.run(["psql", url, "-At", "-F", "\t", "-c", sql], capture_output=True, text=True)
    if r.returncode:
        sys.exit(r.stderr.strip())
    return r.stdout


def public_ip(s: str):
