// Server-only IP → ISO country lookup using the bundled geoip-lite dataset.
//
// This is the fallback that makes display-currency geo work WITHOUT a CDN in
// front: when no `cf-ipcountry` / `x-vercel-ip-country` / `x-nxeon-country`
// header is present (see lib/geo-currency.ts), we resolve the visitor's country
// from their IP locally. geoip-lite ships its own country database, so there's
// no MaxMind license or per-request external API call. If Cloudflare (or nginx
// GeoIP) is added later, the header path wins and this never runs.
//
// Node runtime only (geoip-lite reads its data files from disk) — never import
// into a client/edge bundle.

import "server-only";
import geoip from "geoip-lite";

/** Extract the real client IP from proxy headers (nginx sets X-Real-IP and the
 *  X-Forwarded-For chain; we trust the first hop). Returns null if unusable. */
export function clientIpFromHeaders(hdrs: Headers): string | null {
  const real = hdrs.get("x-real-ip")?.trim();
  if (real) return real;
  const fwd = hdrs.get("x-forwarded-for");
  if (fwd) {
    const first = fwd.split(",")[0]?.trim();
    if (first) return first;
  }
  return null;
}

/** ISO-3166 alpha-2 country for an IP, or null. Private/loopback/unknown → null. */
export function countryFromIp(ip: string | null | undefined): string | null {
  if (!ip) return null;
  // Skip private/loopback ranges — geoip returns null anyway, but cheap to guard.
  if (
    ip === "127.0.0.1" ||
    ip === "::1" ||
    ip.startsWith("10.") ||
    ip.startsWith("192.168.") ||
    /^172\.(1[6-9]|2\d|3[01])\./.test(ip)
  ) {
    return null;
  }
  try {
    const hit = geoip.lookup(ip);
    const cc = hit?.country?.trim().toUpperCase();
    return cc && cc.length === 2 ? cc : null;
  } catch {
    return null;
  }
}

