import type { DirEntry } from "@/lib/server-directory";
import { attributionForKey as attributionFor } from "@/lib/directory-attribution";

/**
 * PURE helpers for the customer-portal directory (/dashboard/directory): the row shape, how a directory entry
 * found on a third-party list becomes a row, and the filters. Kept out of the client component so the query and
 * filter rules are unit-tested (test/directory-portal.test.ts).
 */
export type DirectoryRow = {
  key: string;
  name: string;
  description: string | null;
  address: string;
  family: string;
  gameLabel: string;
  art: string | null;
  variant: string | null;
  slots: number | null;
  region: string | null;
  regionLabel: string | null;
  regionCountry: string | null;
  isFree: boolean;
  /** Whether this game answers a public query at all. */
  queryable: boolean;
  online: number | null;
  onlineMax: number | null;
  motd: string | null;
  map: string | null;
  /** Nxeon-operated community server (FreePublicServer): shown first, links to its join page. */
  community?: boolean;
  joinHref?: string | null;
  password?: string | null;
  /** "nxeon" (hosted by Nxeon, the default) or "external" (found on a public list and checked by us). */
  origin?: "nxeon" | "external";
  /** Source attribution key for external rows: "steam" | "vintagestory" | "truckersmp". */
  attribution?: string | null;
  /** ms epoch Nxeon's own direct check last got an answer (external rows). */
  checkedAt?: number | null;
  /** ms epoch the source list last had this row (external rows). */
  seenAt?: number | null;
};

export const isExternalRow = (r: Pick<DirectoryRow, "origin">) => r.origin === "external";

/** Ordinary Intl region names; falls back to the code. */
export function countryName(code: string | null | undefined): string | null {
  if (!code || !/^[A-Za-z]{2}$/.test(code)) return null;
  try { return new Intl.DisplayNames(["en"], { type: "region" }).of(code.toUpperCase()) ?? code.toUpperCase(); } catch { return code.toUpperCase(); }
}

/** A directory entry that came from a third-party source, as a portal card. Only `source: "external"` entries qualify. */
export function externalEntryToRow(e: DirEntry, meta: { gameLabel: string; art: string | null; queryable: boolean }): DirectoryRow | null {
  if (e.source !== "external") return null;
  const cc = e.country && /^[A-Za-z]{2}$/.test(e.country) ? e.country.toUpperCase() : null;
  return {
    key: e.key, name: e.name, description: e.description || null, address: e.address,
    family: e.game, gameLabel: meta.gameLabel, art: meta.art, variant: null, slots: e.maxPlayers,
    region: cc, regionLabel: countryName(cc), regionCountry: cc,
    isFree: false, queryable: meta.queryable,
    online: e.players, onlineMax: e.players !== null ? e.maxPlayers : null,
    motd: null, map: /^Map: (.+)$/.exec(e.description)?.[1] ?? null,
    origin: "external", attribution: e.attribution ?? null, checkedAt: e.checkedAt ?? null, seenAt: e.seenAt,
  };
}

/** The attribution lines the page must show: one per source present among the rows, no duplicates. */
export function attributionsForRows(rows: Pick<DirectoryRow, "attribution">[]): { key: string; text: string; url: string; linkLabel: string }[] {
  const keys = [...new Set(rows.map((r) => r.attribution).filter((k): k is string => !!k))].sort();
  return keys.map((k) => attributionFor(k)).filter((a): a is NonNullable<typeof a> => !!a);
}

export type RowFilters = {
  q?: string; game?: string; region?: string; onlyLive?: boolean;
  /** all | nxeon (hosted by Nxeon) | external (found on public lists) */
  origin?: "all" | "nxeon" | "external";
};

export function filterRows<T extends DirectoryRow>(rows: T[], f: RowFilters): T[] {
  const needle = (f.q ?? "").trim().toLowerCase();
  return rows.filter((r) => {
    if (f.game && f.game !== "all" && r.family !== f.game) return false;
    if (f.region && f.region !== "all" && r.region !== f.region) return false;
    if (f.onlyLive && !(r.online !== null && r.online > 0)) return false;
    if (f.origin === "nxeon" && isExternalRow(r)) return false;
    if (f.origin === "external" && !isExternalRow(r)) return false;
    if (needle && !`${r.name} ${r.description ?? ""} ${r.motd ?? ""} ${r.address} ${r.gameLabel}`.toLowerCase().includes(needle)) return false;
    return true;
  });
}

/** Servers hosted on Nxeon first (community, then the rest), then external by players; stable by name. */
export function sortRows<T extends DirectoryRow>(rows: T[]): T[] {
  const rank = (r: T) => (r.community ? 0 : isExternalRow(r) ? 2 : 1);
  return [...rows].sort((a, b) => rank(a) - rank(b) || (b.online ?? -1) - (a.online ?? -1) || a.name.localeCompare(b.name));
}

/** "Checked 4 min ago" / "Listed 2 h ago" label for an external card. Never says "live" without our own check. */
export function liveLabel(r: Pick<DirectoryRow, "checkedAt" | "seenAt">, now = Date.now()): { kind: "checked" | "listed" | "none"; text: string } {
  const ago = (t: number) => {
    const m = Math.max(0, Math.round((now - t) / 60_000));
    return m < 1 ? "just now" : m < 60 ? `${m} min ago` : m < 2880 ? `${Math.round(m / 60)} h ago` : `${Math.round(m / 1440)} d ago`;
  };
  if (r.checkedAt) return { kind: "checked", text: `Checked ${ago(r.checkedAt)}` };
  if (r.seenAt) return { kind: "listed", text: `Seen on the list ${ago(r.seenAt)}` };
  return { kind: "none", text: "" };
}

