/**
 * Ingest public servers from the Steam master list into the directory's
 * ExternalServer table (growth item seo-026).
 *
 *   STEAM_WEB_API_KEY=... npx tsx scripts/directory-ingest.ts [--game valheim,projectzomboid] [--limit 1000] [--apply]
 *
 * DRY RUN by default: fetches, parses, dedupes against everything Nxeon hosts,
 * prints counts, writes nothing. --apply writes, and ONLY when
 * Setting directory_ingest_enabled is true (flip it at /admin/directory).
 *
 * `--apply` is blocked until the legal checkpoints are recorded at /admin/directory (country where the
 * Steam data is stored, who read https://steamcommunity.com/dev/apiterms). One request per game per run;
 * the scheduled path is the worker sweep (lib/directory-ingest/sweep.ts), this script is the manual one.
 * `--game all` runs every supported game.
 */
import { ingestValveGame } from "../lib/directory-ingest/run";
import { VALVE_APPIDS, ALL_STEAM_APPIDS } from "../lib/directory-ingest/valve";

async function main() {
  const arg = (n: string) => { const i = process.argv.indexOf(`--${n}`); return i >= 0 ? process.argv[i + 1] : undefined; };
  const apply = process.argv.includes("--apply");
  const key = process.env.STEAM_WEB_API_KEY;
  if (!key) { console.error("STEAM_WEB_API_KEY is not set (a free Steam Web API key)."); process.exit(2); }
  const games = (arg("game") === "all" ? Object.keys(VALVE_APPIDS).join(",") : arg("game") ?? "valheim,projectzomboid").split(",").map((s) => s.trim()).filter(Boolean);
  const bad = games.filter((g) => !ALL_STEAM_APPIDS[g]);
  if (bad.length) { console.error(`Unsupported: ${bad.join(", ")}. Supported: ${Object.keys(ALL_STEAM_APPIDS).join(", ")}`); process.exit(2); }
  const limit = arg("limit") ? Number(arg("limit")) : 1000;
  let failed = 0;
  for (const g of games) {
    try {
      const r = await ingestValveGame(g, { apply, key, limit, trigger: "cli" });
      console.log(`${r.dryRun ? "DRY " : "DONE"} ${g}: fetched ${r.fetched}, new ${r.inserted}, updated ${r.updated}, duplicates dropped ${r.duplicates}, blocked (other hosts) ${r.blocked}, pruned ${r.pruned}${r.suspicious ? " (SUSPICIOUS shrink: nothing pruned)" : ""}`);
    } catch (e) {
      failed++;
      console.error(`FAIL ${g}: ${e instanceof Error ? e.message : e}`);
    }
  }
  process.exit(failed ? 1 : 0);
}
main();
