/**
 * ISO-3166 alpha-2 country -> continent, PURE and client-safe (no geoip, no server-only), plus the
 * region-balanced selection the directory uses so one continent cannot crowd out the rest.
 *
 * Continents: NA North America (incl. Central America + Caribbean), SA South America, EU Europe (incl. Russia,
 * Turkey, the Caucasus), AS Asia (incl. the Middle East), OC Oceania, AF Africa. Antarctica and unknown codes -> null.
 */
export type Continent = "NA" | "SA" | "EU" | "AS" | "OC" | "AF";

export const CONTINENT_LABELS: Record<Continent, string> = {
  NA: "North America", SA: "South America", EU: "Europe", AS: "Asia", OC: "Oceania", AF: "Africa",
};
export const CONTINENT_ORDER: readonly Continent[] = ["NA", "SA", "EU", "AS", "OC", "AF"];

const SPEC: Record<Continent, string> = {
  NA: "US CA MX GT BZ SV HN NI CR PA CU JM HT DO BS BB TT AG DM GD KN LC VC PR VI VG AI AW BM KY MS TC CW SX BQ BL MF GP MQ PM GL",
  SA: "BR AR CL CO PE VE EC BO PY UY GY SR GF FK",
  EU: "GB IE FR DE ES PT IT NL BE LU CH AT DK SE NO FI IS PL CZ SK HU RO BG GR HR SI RS BA ME MK AL XK MD UA BY LT LV EE RU MT CY TR GE AM AZ LI MC SM VA AD GI IM JE GG FO AX SJ",
  AS: "CN JP KR KP TW HK MO MN IN PK BD LK NP BT MV AF IR IQ SY LB JO IL PS SA AE QA KW BH OM YE KZ UZ TM KG TJ TH VN LA KH MM MY SG ID PH BN TL",
  OC: "AU NZ FJ PG SB VU WS TO KI FM MH PW NR TV NC PF GU MP AS CK NU TK WF NF",
  AF: "ZA EG NG KE ET GH TZ UG DZ MA TN LY SD SS SN CI CM AO MZ ZW ZM BW NA MW MG RW BI CD CG GA GQ TD NE ML BF GN SL LR TG BJ MR GM GW CV ST SC MU KM DJ ER SO LS SZ RE YT EH SH",
};

const TABLE = new Map<string, Continent>();
for (const c of CONTINENT_ORDER) for (const cc of SPEC[c].split(" ")) TABLE.set(cc, c);

/** Continent for an ISO-2 code (any case, surrounding space ok), or null when unknown. */
export function continentOf(code: string | null | undefined): Continent | null {
  if (!code) return null;
  return TABLE.get(code.trim().toUpperCase()) ?? null;
}

/** Every ISO-2 code mapped to a continent (uppercase). For "country IN (...)" queries. */
export function countriesOf(c: Continent): string[] {
  return SPEC[c].split(" ");
}

/** Bucket key: the continent, or "??" for rows with no/unknown country. */
export type Bucket = Continent | "??";
export const bucketOf = (code: string | null | undefined): Bucket => continentOf(code) ?? "??";

/**
 * Pick at most `total` items so every bucket present gets a fair share: water-filling. Each pass splits the
 * remaining quota evenly over buckets that still have unpicked items; a bucket with fewer than its share gives
 * the surplus back. Within a bucket the input order is kept (callers pass the best first), and the result keeps
 * the input's overall order, so ranking is unchanged. Deterministic. Pure.
 */
export function balanceByContinent<T>(items: T[], countryOf: (x: T) => string | null | undefined, total: number): T[] {
  if (total <= 0) return [];
  if (items.length <= total) return items;
  const buckets = new Map<Bucket, number[]>();
  items.forEach((x, i) => {
    const b = bucketOf(countryOf(x));
    const l = buckets.get(b);
    if (l) l.push(i); else buckets.set(b, [i]);
  });
  const take = new Map<Bucket, number>();
  let left = total;
  let open = [...buckets.keys()];
  while (left > 0 && open.length) {
    const share = Math.max(1, Math.floor(left / open.length));
    const next: Bucket[] = [];
    for (const b of open) {
      const have = buckets.get(b)!.length - (take.get(b) ?? 0);
      const n = Math.min(share, have, left);
      take.set(b, (take.get(b) ?? 0) + n);
      left -= n;
      if (have - n > 0) next.push(b);
      if (left <= 0) break;
    }
    open = next;
  }
  const keep = new Set<number>();
  for (const [b, idx] of buckets) for (const i of idx.slice(0, take.get(b) ?? 0)) keep.add(i);
  return items.filter((_, i) => keep.has(i));
}
