/**
 * Optional offline country lookup for ingested rows (geoip-lite's bundled dataset: no network). NEVER throws:
 * if the package or its data files cannot load, every lookup is simply "unknown" and ingest carries on.
 * geoip-lite must stay in next.config.ts serverExternalPackages. The accurate fill is still the owner's
 * /root/nxeon-directory-locate.py; ingest never overwrites a country that is already stored.
 */
type Lookup = (ip: string) => { country?: string } | null;
let loaded: Lookup | null | undefined;

async function load(): Promise<Lookup | null> {
  if (loaded !== undefined) return loaded;
  try {
    const m = (await import("geoip-lite")) as unknown as { default?: { lookup: Lookup }; lookup?: Lookup };
    const g = m.default ?? m;
    loaded = typeof g.lookup === "function" ? (ip) => g.lookup!(ip) : null;
  } catch { loaded = null; }
  return loaded;
}

/** ISO-2 (uppercase) per IP, only for IPs the dataset knows. `lookup` is injectable for tests. */
export async function countriesForIps(ips: string[], lookup?: Lookup | null): Promise<Map<string, string>> {
  const out = new Map<string, string>();
  try {
    const fn = lookup === undefined ? await load() : lookup;
    if (!fn) return out;
    for (const ip of new Set(ips)) {
      try {
        const cc = fn(ip)?.country?.trim().toUpperCase();
        if (cc && /^[A-Z]{2}$/.test(cc)) out.set(ip, cc);
      } catch { /* one bad lookup is just "unknown" */ }
    }
  } catch { /* optional */ }
  return out;
}
EOF
