  await assert.rejects(fetchValveList("valheim", { key: "SECRETKEY", fetchImpl: boom, delayMs: 0 }), (e: unknown) => e instanceof ValveFetchError && !e.message.includes("SECRETKEY") && !e.message.includes("steampowered"));
