  await m.db.externalServer.updateMany({ where: { game: "valheim" }, data: { country: "CA" } });
  await ingestValveGame("valheim", { apply: true, key: "K", fetchImpl: f, reverse, regionDelayMs: 0, regions: [255] });
  assert.equal((await m.db.externalServer.findFirstOrThrow({ where: { game: "valheim" } })).country, "CA", "never overwritten");
