  const row = (i: number, cc: string | null, players: number) => ({
    source: "valve", sourceKey: `7.${cc === "SG" ? 1 : cc === "DE" ? 2 : 3}.${Math.floor(i / 200)}.${i % 200 + 1}:2456`, game: "valheim", name: `Bal ${cc} ${i}`,
    host: `7.${cc === "SG" ? 1 : cc === "DE" ? 2 : 3}.${Math.floor(i / 200)}.${i % 200 + 1}`, port: 2456, country: cc, players, maxPlayers: 20, tags: [],
    connKey: `k-${cc}-${i}`, ipKey: `k-${cc}-${i}`, lastSeenAt: new Date(),
  });
  await m.db.externalServer.createMany({ data: [
    ...Array.from({ length: 1500 }, (_, i) => row(i, "SG", 19)),
    ...Array.from({ length: 40 }, (_, i) => row(i, "DE", 1)),
    ...Array.from({ length: 40 }, (_, i) => row(i, "BR", 0)),
  ] });
  const { entries } = await m.loadDirectory({ game: "valheim" });
  const by = (cc: string) => entries.filter((e) => e.country === cc).length;
  assert.equal(by("DE"), 40); assert.equal(by("BR"), 40);
  assert.ok(entries.length <= 1000 && by("SG") >= 900, `SG ${by("SG")} of ${entries.length}`);
});
EOF
